    "app.engineTuning.delegationHelp": "Rozdzielanie pracy między agentów pomocniczych. Wywołania narzędzi w ramach jednej tury są zawsze wykonywane kolejno; tylko delegowanie pozwala Jenny pracować równolegle.",
